"""Deterministic K-fold splitting of the LabelMe crack dataset.

The fold manifest is the single source of truth shared by teacher training
(Stage B), student distillation (Stage C) and evaluation, so every experiment
uses the exact same train/val/test assignment.
"""
from __future__ import annotations

import json
import random
from pathlib import Path
from typing import Any, Optional

from PIL import Image, UnidentifiedImageError

from scripts.labelme_crack_copy_paste import read_labelme

IMAGE_SUFFIXES = (".png", ".jpg", ".jpeg", ".bmp", ".webp", ".tif", ".tiff", ".JPG", ".JPEG")


def resolve_labelme_image(images_dir: Path, ann_path: Path, data: dict[str, Any]) -> Optional[Path]:
    search_dirs = [ann_path.parent, images_dir]
    sub_images = images_dir / "images"
    if sub_images.is_dir():
        search_dirs.append(sub_images)
    deduped: list[Path] = []
    for root in search_dirs:
        if root not in deduped:
            deduped.append(root)

    candidates: list[Path] = []
    image_path = data.get("imagePath")
    for root in deduped:
        if isinstance(image_path, str) and image_path.strip():
            candidates.append(root / Path(image_path).name)
        for suffix in IMAGE_SUFFIXES:
            candidates.append(root / f"{ann_path.stem}{suffix}")
        if ".rf." in ann_path.stem:
            rf_suffix = ann_path.stem.split(".rf.", 1)[-1]
            candidates.extend(sorted(root.glob(f"*.rf.{rf_suffix}.*")))
            candidates.extend(sorted(root.glob(f"*{rf_suffix}*")))

    seen: set[Path] = set()
    for p in candidates:
        if p in seen:
            continue
        seen.add(p)
        if p.is_file() and p.suffix.lower() in {s.lower() for s in IMAGE_SUFFIXES}:
            return p
    return None


def is_valid_image(path: Path) -> bool:
    try:
        with Image.open(path) as im:
            im.verify()
        return True
    except (UnidentifiedImageError, OSError, ValueError):
        return False


def discover_samples(labelme_dir: Path, images_dir: Optional[Path] = None) -> list[dict[str, str]]:
    """Return all LabelMe samples (json + resolvable image) as dicts."""
    images_dir = images_dir or labelme_dir
    samples: list[dict[str, str]] = []
    for ann_path in sorted(labelme_dir.glob("*.json")):
        data = read_labelme(ann_path)
        img_path = resolve_labelme_image(images_dir, ann_path, data)
        if img_path is None or not is_valid_image(img_path):
            continue
        samples.append(
            {"stem": ann_path.stem, "json": str(ann_path), "image": str(img_path)}
        )
    return samples


def build_kfold(samples: list[dict[str, str]], k: int = 5, seed: int = 42) -> dict[str, Any]:
    """Deterministically assign samples to ``k`` folds (round-robin after shuffle)."""
    if k < 2:
        raise ValueError("k must be >= 2")
    if len(samples) < k:
        raise ValueError(f"Not enough samples ({len(samples)}) for {k} folds")
    rng = random.Random(seed)
    order = list(range(len(samples)))
    rng.shuffle(order)
    folds: list[list[dict[str, str]]] = [[] for _ in range(k)]
    for pos, idx in enumerate(order):
        folds[pos % k].append(samples[idx])
    return {
        "k": int(k),
        "seed": int(seed),
        "num_samples": len(samples),
        "folds": folds,
    }


def save_folds(split: dict[str, Any], path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(split, ensure_ascii=False, indent=2), encoding="utf-8")


def load_folds(path: Path) -> dict[str, Any]:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except UnicodeDecodeError:
        return json.loads(path.read_text(encoding="utf-8-sig"))


def to_tuples(samples: list[dict[str, str]]) -> list[tuple[Path, Path]]:
    return [(Path(s["json"]), Path(s["image"])) for s in samples]


def fold_train_val_test(
    split: dict[str, Any],
    held_out_fold: int,
    val_ratio: float,
    seed: int,
) -> tuple[list[dict[str, str]], list[dict[str, str]], list[dict[str, str]]]:
    """Return (train, val, test) sample dicts for one held-out fold.

    ``test`` = the held-out fold. ``train``/``val`` are drawn from the remaining
    folds, with ``val`` being an internal ``val_ratio`` subset used for early
    stopping only.
    """
    folds = split["folds"]
    k = int(split["k"])
    if not (0 <= held_out_fold < k):
        raise ValueError(f"held_out_fold {held_out_fold} out of range for k={k}")

    test = list(folds[held_out_fold])
    train_pool: list[dict[str, str]] = []
    for f in range(k):
        if f != held_out_fold:
            train_pool.extend(folds[f])

    rng = random.Random(seed)
    pool = list(train_pool)
    rng.shuffle(pool)
    n_val = max(1, int(len(pool) * val_ratio)) if len(pool) > 1 else 0
    val = pool[:n_val]
    train = pool[n_val:] if n_val > 0 else pool
    return train, val, test

"""Shared image-level crack IoU validation for early stopping and evaluation.

Used by Stage B (teacher), Stage C (student) and the final eval script so that
the model-selection metric is identical to the reported metric.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Any

import numpy as np
import torch
import torch.nn.functional as F

from scripts.labelme_crack_copy_paste import rasterize_masks

MEAN = np.array([0.485, 0.456, 0.406], dtype=np.float32)
STD = np.array([0.229, 0.224, 0.225], dtype=np.float32)
CRACK_CLASS = 1
IGNORE_INDEX = 255


def effective_ignore(ignore_manual: np.ndarray, component: np.ndarray) -> np.ndarray:
    return ignore_manual | (~component)


@dataclass
class CrackMetrics:
    tp: int
    fp: int
    fn: int
    valid_pixels: int

    @property
    def iou(self) -> float:
        return float(self.tp) / float(self.tp + self.fp + self.fn + 1e-6)

    @property
    def precision(self) -> float:
        return float(self.tp) / float(self.tp + self.fp + 1e-6)

    @property
    def recall(self) -> float:
        return float(self.tp) / float(self.tp + self.fn + 1e-6)

    @property
    def f1(self) -> float:
        return 2.0 * self.precision * self.recall / (self.precision + self.recall + 1e-6)

    def as_dict(self) -> dict[str, float]:
        return {
            "iou": self.iou,
            "f1": self.f1,
            "precision": self.precision,
            "recall": self.recall,
            "tp": float(self.tp),
            "fp": float(self.fp),
            "fn": float(self.fn),
            "valid_pixels": float(self.valid_pixels),
        }


def sliding_starts(length: int, patch: int, stride: int) -> list[int]:
    if length <= patch:
        return [0]
    starts = list(range(0, length - patch + 1, stride))
    if starts[-1] != length - patch:
        starts.append(length - patch)
    return starts


def crop_bottom_right_pad(image: np.ndarray, x: int, y: int, size: int) -> tuple[np.ndarray, int, int]:
    h, w = image.shape[:2]
    crop_w = min(size, w - x)
    crop_h = min(size, h - y)
    patch = np.zeros((size, size, 3), dtype=np.uint8)
    patch[:crop_h, :crop_w] = image[y : y + crop_h, x : x + crop_w]
    return patch, crop_w, crop_h


def crop_center_pad(image: np.ndarray, x: int, y: int, size: int) -> tuple[np.ndarray, tuple[int, int, int, int]]:
    h, w = image.shape[:2]
    x2 = min(x + size, w)
    y2 = min(y + size, h)
    crop = image[y:y2, x:x2]
    patch = np.zeros((size, size, 3), dtype=np.uint8)
    top = (size - crop.shape[0]) // 2
    left = (size - crop.shape[1]) // 2
    patch[top : top + crop.shape[0], left : left + crop.shape[1]] = crop
    return patch, (top, left, crop.shape[0], crop.shape[1])


def image_to_tensor_imagenet(image_np: np.ndarray) -> torch.Tensor:
    x = image_np.astype(np.float32) / 255.0
    x = (x - MEAN) / STD
    return torch.from_numpy(np.transpose(x, (2, 0, 1)))


def image_to_tensor_01(image_np: np.ndarray) -> torch.Tensor:
    x = image_np.astype(np.float32) / 255.0
    return torch.from_numpy(np.transpose(x, (2, 0, 1)))


def build_gt_masks(
    data: dict[str, Any],
    size: tuple[int, int],
    *,
    crack_labels: set[str],
    ignore_labels: set[str],
    component_labels: set[str],
) -> tuple[np.ndarray, np.ndarray]:
    w, h = size
    crack, ignore, component, _other = rasterize_masks(
        data,
        (w, h),
        crack_labels,
        ignore_labels,
        component_labels,
        treat_empty_component_as_full_image=False,
    )
    ignore_eff = effective_ignore(ignore, component)
    gt = np.zeros((h, w), dtype=np.uint8)
    gt[crack] = CRACK_CLASS
    gt[ignore_eff] = IGNORE_INDEX
    valid = component & (~ignore_eff)
    return gt, valid


def compute_crack_metrics(gt: np.ndarray, pred: np.ndarray, valid: np.ndarray) -> CrackMetrics:
    if not bool(valid.any()):
        return CrackMetrics(0, 0, 0, 0)
    gt_c = (gt == CRACK_CLASS) & valid
    pred_c = (pred == CRACK_CLASS) & valid
    tp = int(np.logical_and(gt_c, pred_c).sum())
    fp = int(np.logical_and(~gt_c, pred_c).sum())
    fn = int(np.logical_and(gt_c, ~pred_c).sum())
    return CrackMetrics(tp=tp, fp=fp, fn=fn, valid_pixels=int(valid.sum()))


def aggregate_micro(metrics_list: list[CrackMetrics]) -> CrackMetrics:
    return CrackMetrics(
        tp=sum(m.tp for m in metrics_list),
        fp=sum(m.fp for m in metrics_list),
        fn=sum(m.fn for m in metrics_list),
        valid_pixels=sum(m.valid_pixels for m in metrics_list),
    )


def aggregate_macro(metrics_list: list[CrackMetrics]) -> dict[str, float]:
    if not metrics_list:
        return {"iou": 0.0, "f1": 0.0, "precision": 0.0, "recall": 0.0}
    vals = [m.as_dict() for m in metrics_list if m.valid_pixels > 0]
    if not vals:
        return {"iou": 0.0, "f1": 0.0, "precision": 0.0, "recall": 0.0}
    return {
        "iou": float(np.mean([v["iou"] for v in vals])),
        "f1": float(np.mean([v["f1"] for v in vals])),
        "precision": float(np.mean([v["precision"] for v in vals])),
        "recall": float(np.mean([v["recall"] for v in vals])),
    }


@torch.no_grad()
def predict_teacher_mask(
    model: torch.nn.Module,
    image_rgb: np.ndarray,
    *,
    imgsz: int,
    stride: int,
    num_classes: int,
    device: torch.device,
) -> np.ndarray:
    """Sliding-window binary crack mask prediction for a DINOv3 Stage-B teacher."""
    h, w = image_rgb.shape[:2]
    acc = np.zeros((num_classes, h, w), dtype=np.float32)
    cnt = np.zeros((h, w), dtype=np.float32)
    use_amp = device.type == "cuda"
    for y in sliding_starts(h, imgsz, stride):
        for x in sliding_starts(w, imgsz, stride):
            patch, (top, left, crop_h, crop_w) = crop_center_pad(image_rgb, x, y, imgsz)
            t = image_to_tensor_imagenet(patch).unsqueeze(0).to(device)
            with torch.amp.autocast("cuda", enabled=use_amp):
                logits = model(t)
            logits_np = logits[0, :, top : top + crop_h, left : left + crop_w].float().cpu().numpy()
            acc[:, y : y + crop_h, x : x + crop_w] += logits_np
            cnt[y : y + crop_h, x : x + crop_w] += 1.0
    acc /= np.maximum(cnt[None, :, :], 1e-6)
    pred = np.argmax(acc, axis=0).astype(np.uint8)
    if num_classes > 2:
        pred = (pred == CRACK_CLASS).astype(np.uint8)
    return pred


@torch.no_grad()
def predict_student_mask(
    model: torch.nn.Module,
    image_rgb: np.ndarray,
    *,
    imgsz: int,
    stride: int,
    num_classes: int,
    device: torch.device,
) -> np.ndarray:
    """Sliding-window binary crack mask prediction for the YOLO-U-Net student."""
    h, w = image_rgb.shape[:2]
    prob_sum = np.zeros((num_classes, h, w), dtype=np.float32)
    count = np.zeros((h, w), dtype=np.float32)
    for y in sliding_starts(h, imgsz, stride):
        for x in sliding_starts(w, imgsz, stride):
            patch, crop_w, crop_h = crop_bottom_right_pad(image_rgb, x, y, imgsz)
            tensor = image_to_tensor_01(patch).unsqueeze(0).to(device)
            logits, _ = model(tensor)
            prob = F.softmax(logits.float(), dim=1)[0, :, :crop_h, :crop_w].cpu().numpy()
            prob_sum[:, y : y + crop_h, x : x + crop_w] += prob
            count[y : y + crop_h, x : x + crop_w] += 1.0
    prob_sum /= np.maximum(count[None, :, :], 1.0)
    return np.argmax(prob_sum, axis=0).astype(np.uint8)

