def masked_smooth_l1(student: torch.Tensor, teacher: torch.Tensor, valid: torch.Tensor, eps: float = 1e-6) -> torch.Tensor:
    if valid.dim() == 3:
        valid = valid[:, None]
    valid = valid.to(device=student.device, dtype=student.dtype)
