            for t in t_layers:
                vals.append(t[m].detach().float())
        if not vals:
            return
        batch_center = torch.cat(vals, dim=0).mean(dim=0, keepdim=True)
        self.center.mul_(self.center_momentum).add_(batch_center * (1.0 - self.center_momentum))


